// Preserve null/stationary samples and time gaps in the compact pace trace.
export function paceTrace(records) {
  const values=records.filter(r=>Number.isFinite(r.speed)&&r.speed>=1000/3600).map(r=>1000/r.speed);
  const end=records.at(-1)?.t;
  if(!values.length||!(end>0))return '';
  const min=Math.min(...values),max=Math.max(...values);
  let d='',drawing=false;
  for(let i=0;i<records.length;i++){
    const r=records[i];
    if(!Number.isFinite(r.speed)||r.speed<1000/3600){drawing=false;continue;}
    if(i&&r.t-records[i-1].t>30)drawing=false;
    d+=`${drawing?'L':'M'}${(r.t/end*600).toFixed(2)},${(12+(1000/r.speed-min)/Math.max(max-min,1)*60).toFixed(2)} `;drawing=true;
  }
  return d;
}

export function fieldNotesView({activity,icon,logo,dateText,distance,duration,paceText,summaryPace,escape,routePanel,stats,observationPanel,analysisPanel,blocksPanel,sourceNote,inlineCheckin,miniRoute,reduced,systemReduced,persisted=false,cloud=false}) {
  const gps=activity.records.some(r=>r.lat!==null&&r.lon!==null);
  const canReplay=gps&&activity.records.length>1&&activity.records.at(-1).t>0;
  const trace=activity.distance>=10?paceTrace(activity.records):'';
  return `<header class="fn-header"><a href="/" class="fn-brand" aria-label="My Fitness Analyser home">${logo}<span>My Fitness Analyser<small>Your training, collected.</small></span></a><nav aria-label="Activity navigation"><a href="/training">Training</a><a href="/journal">Journal</a>${cloud?'<a href="/account">Account</a>':''}<button data-action="activities">Activities</button><a href="#session-details">In detail</a><button data-action="checkin">Your notes</button></nav><div class="fn-header-actions"><button class="fn-motion" data-action="motion" aria-pressed="${!reduced}" ${systemReduced?'disabled':''} aria-label="${systemReduced?'Motion follows system reduced-motion setting':'Toggle visual motion'}"><i aria-hidden="true"></i><span>${systemReduced?'System motion off':reduced?'Motion off':'Motion on'}</span></button><button class="icon-button" data-action="source" aria-label="Activity sources">${icon('layers')}</button><button class="fn-avatar" data-action="review" aria-label="Preview settings">S</button></div><div class="fn-reading-progress" aria-hidden="true"></div></header>
  <main id="main" class="fn-main">
    <section class="fn-hero" aria-labelledby="activity-title" id="overview">
      <div class="fn-aura" aria-hidden="true"></div>
      <div class="fn-intro"><p class="fn-date">${escape(activity.sport)} <span></span> ${dateText(activity.date)}${activity.time?`<span class="fn-time">${escape(activity.time)}</span>`:''}</p><h1 id="activity-title">${escape(activity.title)}</h1><div class="fn-source"><span class="fn-source-dot"></span>${escape(activity.source)}${activity.synthetic?'<span class="synthetic-label">Synthetic data</span>':''}<button data-action="source" class="text-button" aria-label="View activity provenance">${icon('info')}</button></div></div>
      <div class="fn-art"><div class="fn-glint" aria-hidden="true"></div><div class="fn-course-grid" aria-hidden="true"></div>${routePanel()}<div class="fn-replay-controls"><button class="fn-replay" data-action="route-replay" aria-pressed="false" ${!canReplay||reduced?'disabled':''}>${icon('play')}<span>${!canReplay?'Replay unavailable':reduced?'Replay · motion off':'Replay route'}</span></button><span>${canReplay?'12-second visual preview':'Summary preserved'}</span><div class="fn-replay-readout"><strong id="replay-time">${duration(0)}</strong><span id="replay-pace">Select a moment</span></div></div>${trace?`<div class="fn-effort-trace"><div class="fn-trace-label"><span>Pace across the session</span><a href="#session-details">Inspect data ${icon('plus')}</a></div><svg viewBox="0 0 600 84" preserveAspectRatio="none" role="img" aria-label="Recorded pace over elapsed time; faster samples are higher. Inspect using the time slider below."><path class="fn-trace-grid" d="M0 26H600M0 58H600"/><path class="fn-trace-path" d="${trace}"/><path class="fn-trace-cursor" d="M0 0V84"/></svg><label class="sr-only" for="replay-position">Inspect session moment</label><input id="replay-position" type="range" min="0" max="${activity.records.length-1}" value="0" aria-label="Inspect session moment"><div class="fn-trace-times"><span>${duration(0)}</span><span>Elapsed time</span><span>${duration(activity.records.at(-1).t)}</span></div></div>`:''}</div>
      <div class="fn-primary"><div class="fn-distance"><span>${distance(activity.distance)}</span><small>km</small></div><p>${activity.distance!==null&&activity.distance<10?'Distance below 10 m · pace unavailable':'Distance covered'}</p><div class="fn-session-actions"><button class="primary-button" data-action="checkin">Log how it felt ${icon('arrow')}</button><a href="#session-details" class="fn-data-link">Explore session ${icon('chevrondown')}</a></div></div>
      <div class="fn-hero-footer">${stats()}<a class="fn-scroll-cue" href="#session-finding"><span>Explore this session</span>${icon('chevrondown')}</a></div>
    </section>
    <section class="fn-finding fn-chapter" id="session-finding" aria-label="Session observation"><div class="fn-chapter-label"><span class="fn-hairline"></span><span>Session takeaway</span></div>${observationPanel()}<div class="fn-finding-foot"><p>Understand the effort. Add your context.</p><a href="#session-details" class="fn-round-link" aria-label="Explore the session details">${icon('chevrondown')}</a></div></section>
    <section class="fn-details fn-chapter" id="session-details" aria-label="Recorded session details"><aside class="fn-atlas"><div class="fn-chapter-label"><span class="fn-hairline"></span><span>Session analysis</span></div><h2>Trace your<br>effort.</h2><div class="fn-mini-map">${gps?`<div class="route-svg">${miniRoute}</div>`:`<div class="fn-missing-route">${icon('route')}<p>No GPS in this record.<br>Your session facts are preserved.</p></div>`}</div><div class="fn-atlas-caption"><span class="route-selection">Full activity</span><span>${gps?'Recorded GPS outline':'Source summary'}</span></div><p class="fn-atlas-note">${gps?'Choose a time block to connect the route and chart.':'Available summaries and displayed splits stay intact.'}</p></aside><div class="fn-detail-content">${analysisPanel()}${blocksPanel()}</div></section>
    ${sourceNote()}
    <section class="fn-notes-section fn-chapter"><div class="fn-notes-aside"><div class="fn-chapter-label"><span class="fn-hairline"></span><span>Post-session check-in</span></div><h2>Effort is personal.<br>Capture yours.</h2><p>How hard. How comfortable. How much left.<br>Four answers to complete your training record.</p><span class="fn-note-mark" aria-hidden="true">${logo}</span></div>${inlineCheckin()}</section>
    <footer class="fn-recap fn-chapter"><div><span class="fn-chapter-label">My Fitness Analyser</span><h2>Your training.<br>In focus.</h2></div><div class="fn-recap-record"><p>${escape(activity.title)}</p><strong>${distance(activity.distance)}<small> km</small></strong><span>${duration(activity.timer??activity.running??activity.moving)} <i></i> ${paceText(summaryPace())} /km</span><button class="text-button" data-action="source">View the source ${icon('plus')}</button></div><div class="fn-recap-bottom"><span>${activity.synthetic?'Synthetic design sample':'Your imported activity'} · ${persisted?(cloud?'Check-ins saved privately online':'Check-ins saved on this computer'):'Check-ins stay in this browser preview'}</span><a href="#overview">Back to the session ${icon('arrow')}</a></div></footer>
  </main>`;
}
